part of 'academy_english_advanced_models.dart';
/// Original A2 Unit 2 lessons, authored independently from Unit 1.
abstract final class EnglishAdvancedA2SecondUnit {
  static const lessons = <EnglishAdvancedLesson>[
    EnglishAdvancedLesson(level:'A2',unitNumber:2,number:1,title:"A Room of Your Own",titleArabic:"غرفة خاصة بك",storyTitle:"A Room of Your Own",storyTitleArabic:"غرفة خاصة بك",paragraphs:<String>["After moving into a shared apartment, Layla finally had a bedroom of her own. She carried a small bookshelf through the doorway and placed it beside the window. The curtains were pale green, and the carpet was soft. She wanted the space to feel comfortable without spending too much money.","Her roommate suggested adding a bedside table and a reading light. Together they measured the wall and moved the furniture to make more space. Layla noticed a loose handle on the wardrobe, so she wrote a maintenance request to the building manager.","That evening, Layla arranged her books, watered a houseplant and invited her roommate for tea. The room looked brighter and more welcoming. She had not bought anything expensive, but she had learned that careful planning could make a small home pleasant."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("bedroom","غرفة نوم"),EnglishAdvancedWord("bookshelf","رف كتب"),EnglishAdvancedWord("doorway","مدخل الباب"),EnglishAdvancedWord("curtains","ستائر"),EnglishAdvancedWord("carpet","سجادة"),EnglishAdvancedWord("roommate","شريك سكن"),EnglishAdvancedWord("bedside table","طاولة بجانب السرير"),EnglishAdvancedWord("furniture","أثاث"),EnglishAdvancedWord("wardrobe","خزانة ملابس"),EnglishAdvancedWord("maintenance request","طلب صيانة")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("floor plan","مخطط أرضية"),EnglishAdvancedWord("rental deposit","تأمين إيجار"),EnglishAdvancedWord("utility payment","دفع المرافق"),EnglishAdvancedWord("storage box","صندوق تخزين"),EnglishAdvancedWord("desk organizer","منظّم مكتب"),EnglishAdvancedWord("wall shelf","رف جداري"),EnglishAdvancedWord("laundry basket","سلة غسيل"),EnglishAdvancedWord("light bulb","مصباح كهربائي"),EnglishAdvancedWord("door handle","مقبض باب"),EnglishAdvancedWord("houseplant","نبتة منزلية"),EnglishAdvancedWord("shared hallway","ممر مشترك"),EnglishAdvancedWord("cleaning schedule","جدول تنظيف"),EnglishAdvancedWord("moving day","يوم الانتقال"),EnglishAdvancedWord("living expenses","نفقات السكن")],grammarTitle:"Too, enough and degree",grammarArabic:"Too تعني أكثر مما نحتاج وتأتي قبل الصفة: too small. وEnough تعني كافٍ، وتأتي بعد الصفة: large enough. يمكن أن نقول enough space.",grammarExamples:<String>["The room is big enough for a desk.","This shelf is too high to reach.","We have enough space for a table."],listening:"Hello, tenants. The building maintenance team will visit on Friday between ten and noon. Please report broken handles, lights or windows by Thursday evening. If you need help moving large furniture, ask the building manager before making arrangements. Remember that the shared kitchen must be cleaned after use. The new cleaning schedule is displayed near the main entrance.",listeningQuestion:"By when should tenants report broken items?",listeningOptions:<String>["Thursday evening","Saturday morning","Next Monday"],listeningAnswer:0,readingQuestion:"Why did Layla contact the building manager?",readingOptions:<String>["A wardrobe handle was loose","She needed a train ticket","The carpet was missing"],readingAnswer:0,writingCue:"Layla had a loose handle on her ____.",writingAnswer:"wardrobe"),
    EnglishAdvancedLesson(level:'A2',unitNumber:2,number:2,title:"The Doctor's Advice",titleArabic:"نصيحة الطبيب",storyTitle:"The Doctor's Advice",storyTitleArabic:"نصيحة الطبيب",paragraphs:<String>["Nabil had felt tired for several days, so he booked a routine appointment at the health clinic. At reception, he completed a short health form and waited in a quiet room. He explained his symptoms carefully when the doctor asked how he had been feeling.","The doctor checked his temperature and asked about his sleep routine, meals and exercise. She explained that several everyday problems can cause tiredness. Rather than guessing the cause, she recommended appropriate tests and a follow-up visit if the symptoms continued.","Nabil wrote the instructions in his notebook and asked questions when he did not understand a term. The doctor encouraged him to contact the clinic if anything changed. He left feeling reassured because he had received clear advice and knew what to do next."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("routine appointment","موعد اعتيادي"),EnglishAdvancedWord("health clinic","عيادة صحية"),EnglishAdvancedWord("reception","استقبال"),EnglishAdvancedWord("health form","نموذج صحي"),EnglishAdvancedWord("appropriate tests","فحوص مناسبة"),EnglishAdvancedWord("temperature","درجة حرارة"),EnglishAdvancedWord("sleep routine","نظام النوم"),EnglishAdvancedWord("exercise","رياضة"),EnglishAdvancedWord("follow-up visit","زيارة متابعة"),EnglishAdvancedWord("instructions","تعليمات")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("medical history","تاريخ مرضي"),EnglishAdvancedWord("appointment reminder","تذكير الموعد"),EnglishAdvancedWord("waiting time","مدة انتظار"),EnglishAdvancedWord("general practitioner","طبيب عام"),EnglishAdvancedWord("health check","فحص صحي"),EnglishAdvancedWord("tiredness","تعب"),EnglishAdvancedWord("blood test","فحص دم"),EnglishAdvancedWord("test results","نتائج فحوص"),EnglishAdvancedWord("patient record","سجل مريض"),EnglishAdvancedWord("health question","سؤال طبي"),EnglishAdvancedWord("reassurance","طمأنة"),EnglishAdvancedWord("clinic hours","ساعات العيادة"),EnglishAdvancedWord("symptom diary","مفكرة أعراض"),EnglishAdvancedWord("professional advice","نصيحة مختص")],grammarTitle:"Present perfect with for and since",grammarArabic:"نستخدم for مع مدة: for three days، وsince مع نقطة زمنية: since Monday. ويمكن أن نقول I have felt tired for three days. لا نستبدل since بـ for أمام يوم محدد.",grammarExamples:<String>["I have felt tired for three days.","She has worked here since Monday.","How long have you had these symptoms?"],listening:"This is a reminder from Green Street Health Clinic. If you have an appointment tomorrow morning, please arrive ten minutes early to complete your patient details. Bring a list of any questions you want to ask the doctor. If you cannot attend, call the reception team before five this evening. Test results are normally discussed with a qualified clinician during a separate appointment.",listeningQuestion:"Why should patients arrive early?",listeningOptions:<String>["To complete their details","To collect a new passport","To attend a sports meeting"],listeningAnswer:0,readingQuestion:"Why did the doctor recommend tests?",readingOptions:<String>["To help understand the cause","Because Nabil was moving house","Because he wanted a new job"],readingAnswer:0,writingCue:"Nabil completed a health ____ at reception.",writingAnswer:"health form"),
    EnglishAdvancedLesson(level:'A2',unitNumber:2,number:3,title:"A Recipe from Home",titleArabic:"وصفة من البيت",storyTitle:"A Recipe from Home",storyTitleArabic:"وصفة من البيت",paragraphs:<String>["Mariam wanted to cook a family meal for her friends. Her grandmother had given her a handwritten recipe for a vegetable stew. Mariam bought the ingredients at the market, washed the vegetables and prepared a large cooking pot before her guests arrived.","First, she chopped the onions and heated a little oil. Then she added tomatoes, spices and water. She stirred the stew slowly while it cooked and tasted the sauce to check its flavor. Her younger brother helped set the table and served fresh bread.","The guests enjoyed the meal and asked Mariam how to make it. She showed them the recipe and explained each step. Although her grandmother lived far away, cooking the same dish made Mariam feel close to her family and eager to share the tradition."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("handwritten recipe","وصفة بخط اليد"),EnglishAdvancedWord("vegetable stew","يخنة خضروات"),EnglishAdvancedWord("family meal","وجبة عائلية"),EnglishAdvancedWord("market stall","بسطة سوق"),EnglishAdvancedWord("cooking pot","قدر طهي"),EnglishAdvancedWord("chopped onions","بصل مفروم"),EnglishAdvancedWord("spices","بهارات"),EnglishAdvancedWord("stirred","حرّك"),EnglishAdvancedWord("sauce","صلصة"),EnglishAdvancedWord("flavor","نكهة")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("measuring spoon","ملعقة قياس"),EnglishAdvancedWord("wooden spoon","ملعقة خشبية"),EnglishAdvancedWord("simmer","يُطهى على نار هادئة"),EnglishAdvancedWord("boil","يغلي"),EnglishAdvancedWord("sauté","يشوّح"),EnglishAdvancedWord("cooking time","وقت الطهي"),EnglishAdvancedWord("serving plate","صحن تقديم"),EnglishAdvancedWord("family tradition","تقليد عائلي"),EnglishAdvancedWord("kitchen towel","منشفة مطبخ"),EnglishAdvancedWord("chopping board","لوح تقطيع"),EnglishAdvancedWord("seasoning","تتبيل"),EnglishAdvancedWord("serving size","حجم التقديم"),EnglishAdvancedWord("leftovers","بقايا طعام"),EnglishAdvancedWord("recipe notebook","دفتر وصفات")],grammarTitle:"Sequence words in a recipe",grammarArabic:"لتقديم التعليمات بترتيب واضح استخدم First وNext وThen وFinally. تبدأ جملة الأمر بالفعل الأساسي: Chop the onions. تجنّب وضع to قبل فعل الأمر.",grammarExamples:<String>["First, wash the vegetables.","Then add the tomatoes to the pot.","Finally, serve the meal with bread."],listening:"Welcome to today's cooking workshop. First, wash your vegetables and prepare the ingredients. Next, chop the onions and heat a little oil in a large pot. Add the tomatoes and spices, then stir the mixture carefully. Allow the stew to cook gently before tasting it. Finally, place the finished dish on a serving plate. Please ask the teacher for help with any unfamiliar kitchen equipment.",listeningQuestion:"What should cooks do just before serving?",listeningOptions:<String>["Taste the stew","Buy a new pot","Leave the kitchen"],listeningAnswer:0,readingQuestion:"Who gave Mariam the handwritten recipe?",readingOptions:<String>["Her grandmother","Her teacher","A shopkeeper"],readingAnswer:0,writingCue:"Mariam cooked a vegetable ____ for her friends.",writingAnswer:"stew"),
  ];
}
